def read(n):
 p=ROOT/n
 for component in [p,*p.parents]:
  if component.is_symlink():raise ValueError('Symlink source: '+str(component))
 if not p.is_file():raise ValueError('Missing regular source: '+n)
 return p.read_text(encoding='utf-8')
